import heapq

def match(orders):
    trades = []
    seq_counter = 0

    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)

    book = {}  # id -> dict with side, price, qty, active

    def add_to_book(oid, side, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def top_valid_buy():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            return negprice, seq, oid
        return None

    def top_valid_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            return price, seq, oid
        return None

    for order in orders:
        otype = order[0]

        if otype == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if otype == 'market':
            _, oid, side, qty = order
            price = None
        else:
            _, oid, side, price, qty = order

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                top = top_valid_sell()
                if top is None:
                    break
                sprice, sseq, soid = top
                if otype != 'market' and sprice > price:
                    break
                info = book[soid]
                trade_qty = min(remaining, info['qty'])
                trades.append([oid, soid, sprice, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] <= 0:
                    info['active'] = False
                    heapq.heappop(sell_heap)
            if otype == 'limit' and remaining > 0:
                add_to_book(oid, side, price, remaining, seq_counter)
                seq_counter += 1
        else:  # sell
            while remaining > 0:
                top = top_valid_buy()
                if top is None:
                    break
                negprice, bseq, boid = top
                bprice = -negprice
                if otype != 'market' and bprice < price:
                    break
                info = book[boid]
                trade_qty = min(remaining, info['qty'])
                trades.append([boid, oid, bprice, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] <= 0:
                    info['active'] = False
                    heapq.heappop(buy_heap)
            if otype == 'limit' and remaining > 0:
                add_to_book(oid, side, price, remaining, seq_counter)
                seq_counter += 1

    return trades

